-- Product activation funnel (#509, D-030): activation_event is global (GLOBAL_TABLES), no RLS, one
-- row per (user, step) holding only the user id, a step and channel from closed lists (CHECKs) and
-- a timestamp: no workspace, matter, email or other content. The user FK cascades, so an account
-- deletion (#303) removes the user's events. The app role may read and insert rows, never update or
-- delete them; the clerk role gets nothing.
-- A new table only: nothing existing is altered or dropped.
CREATE TABLE "activation_event" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"step" text NOT NULL,
	"channel" text,
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "activation_event_step_chk" CHECK (step in ('signed_up', 'workspace_created', 'identifiers_entered', 'discovery_found', 'confirm_grid_done', 'first_court_day_view', 'first_alert', 'first_brief', 'whatsapp_linked', 'invite_sent')),
	CONSTRAINT "activation_event_channel_chk" CHECK (channel is null or channel in ('direct', 'invite', 'whatsapp', 'search', 'social', 'referral', 'other'))
);
